-- M77 additive synthetic fugitive workpapers and independent physical discovery.
-- Earlier migration bytes and rows are preserved. No aggregate emissions total.
create table neuvetra.fugitive_heads(id uuid primary key,company_id uuid not null references neuvetra.companies(id),family text not null check(family in('source','population')),source_id uuid,asset_id text,year integer not null check(year=2025),version_id uuid,revision integer not null default 0,unique(id,company_id),check((family='source' and source_id is not null and asset_id is not null)or(family='population' and source_id is null and asset_id is null)));
create unique index m77_source_identity on neuvetra.fugitive_heads(company_id,year,source_id)where family='source';
create unique index m77_asset_identity on neuvetra.fugitive_heads(company_id,year,asset_id)where family='source';
create unique index m77_population_identity on neuvetra.fugitive_heads(company_id,year)where family='population';
create table neuvetra.fugitive_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.fugitive_versions(id uuid primary key,company_id uuid not null,stream_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,stream_id,version),foreign key(stream_id,company_id)references neuvetra.fugitive_heads(id,company_id),foreign key(previous_version_id,company_id)references neuvetra.fugitive_versions(id,company_id),foreign key(coverage_version_id,company_id)references neuvetra.corporate_inventory_versions(id,company_id));
alter table neuvetra.fugitive_heads add foreign key(version_id,company_id)references neuvetra.fugitive_versions(id,company_id);
create table neuvetra.fugitive_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),foreign key(version_id,company_id)references neuvetra.fugitive_versions(id,company_id));
create unique index m77_review_state on neuvetra.fugitive_reviews(company_id,version_id,coalesce((payload#>>'{dependencies,dependencySha256}'),'source'));
create table neuvetra.fugitive_reports(id uuid primary key,company_id uuid not null,stream_id uuid not null,version_id uuid not null,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(stream_id,company_id)references neuvetra.fugitive_heads(id,company_id),foreign key(version_id,company_id)references neuvetra.fugitive_versions(id,company_id));
create table neuvetra.fugitive_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),family text not null check(family in('source','population')),stream_id uuid,fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.fugitive_audit(sequence bigserial primary key,id uuid not null unique,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
create table neuvetra.fugitive_event_reservations(company_id uuid not null,year integer not null check(year=2025),kind text not null check(kind in('event','contractor_reference','release_reference')),event_key text not null,stream_id uuid not null,asset_id text not null,created_at timestamptz not null,primary key(company_id,year,kind,event_key),foreign key(stream_id,company_id)references neuvetra.fugitive_heads(id,company_id));
do $$declare t text;begin foreach t in array array['fugitive_heads','fugitive_statements','fugitive_versions','fugitive_reviews','fugitive_reports','fugitive_requests','fugitive_audit','fugitive_event_reservations']loop execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m77_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);if t<>'fugitive_heads'then execute format('create trigger m77_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;
revoke all on sequence neuvetra.fugitive_audit_sequence_seq from public,authenticated,neuvetra_runtime;

create function neuvetra.m77_lock(target_company uuid,writing boolean)returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing)then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.fugitive_heads where company_id=target_company order by id for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;
create function neuvetra.m77_current_coverage(target_company uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select v.export_text::jsonb||jsonb_build_object('review',r.payload)from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.corporate_inventory_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company$$;
create function neuvetra.m77_current_workpapers(target_company uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select coalesce(jsonb_agg(v.payload||jsonb_build_object('review',r.payload) order by h.id),'[]')from neuvetra.fugitive_heads h join neuvetra.fugitive_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.fugitive_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company and h.family='source'$$;
create function neuvetra.m77_dependencies(coverage jsonb,workpapers jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with pins as(select coalesce(jsonb_agg(jsonb_build_object('worksheetId',(w->'streamId'),'sourceId',(w#>'{activity,binding,sourceId}'),'assetId',(w#>'{activity,assetId}'),'version',jsonb_build_object('id',(w->'id'),'sha256',(w->'versionSha256')),'decision',case when coalesce((w->'review'),'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',(w#>'{review,id}'),'sha256',(w#>'{review,decisionSha256}'))end)order by (w->>'streamId') collate "C"),'[]')p from jsonb_array_elements(workpapers)w),body as(select jsonb_build_object('coveragePin',case when coverage is null then 'null'::jsonb else jsonb_build_object('id',(coverage->'id'),'sha256',(coverage->'versionSha256'))end,'coverageReviewPin',case when coalesce((coverage->'review'),'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',(coverage#>'{review,id}'),'sha256',(coverage#>'{review,decisionSha256}'))end,'workpaperPins',p)b from pins)select b||jsonb_build_object('dependencySha256',neuvetra.m67_hash(b))from body$$;
create function neuvetra.m77_current_dependencies(target_company uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select neuvetra.m77_dependencies(neuvetra.m77_current_coverage(target_company),neuvetra.m77_current_workpapers(target_company))$$;
create function neuvetra.m77_id(v jsonb)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$begin if jsonb_typeof(v)is distinct from 'string'or (v#>>'{}')!~'^[A-Z0-9][A-Z0-9._-]{0,79}$'then raise exception 'canonical evidence/device identifier required'using errcode='22023';end if;end $$;
create function neuvetra.m77_kg(v jsonb,positive boolean default false)returns numeric language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare s text:=(v#>>'{}');n numeric;begin if jsonb_typeof(v)is distinct from 'string'or s!~'^(0|[1-9][0-9]{0,5})([.][0-9]{1,6})?$'then raise exception 'kg decimal string required'using errcode='22023';end if;n:=s::numeric;if positive and n<=0 then raise exception 'positive kg required'using errcode='22023';end if;return n;end $$;
create function neuvetra.m77_date(v jsonb)returns date language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare s text:=(v#>>'{}');d date;begin if jsonb_typeof(v)is distinct from 'string'or s!~'^2025-[0-9]{2}-[0-9]{2}$'then raise exception '2025 date required'using errcode='22023';end if;d:=s::date;if to_char(d,'YYYY-MM-DD')<>s then raise exception 'real date required'using errcode='22023';end if;return d;end $$;
create function neuvetra.m77_calculate(v jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare k text;r jsonb;linked jsonb;ids text[]:='{}';refs text[]:='{}';release_refs text[]:='{}';total numeric:=0;gwp numeric;locator text;amount numeric;release_mass numeric;begin
perform neuvetra.m71_keys(v,'year,asset_id,gas,equipment,unit,opening_date,closing_date,opening_capacity,closing_capacity,declarations,evidence,refills,releases,zero_activity_evidence,uncertainty');if (v->'year')is distinct from '2025'::jsonb or (v->>'unit')is distinct from 'kg'or (v->>'opening_date')is distinct from '2025-01-01'or (v->>'closing_date')is distinct from '2025-12-31'or neuvetra.m77_kg((v->'opening_capacity'),true)<>neuvetra.m77_kg((v->'closing_capacity'),true)then raise exception 'unsupported year/boundary charge'using errcode='22023';end if;perform neuvetra.m77_id((v->'asset_id'));perform neuvetra.m76_diesel_text((v->'uncertainty'),2000);if length((v->>'uncertainty'))<20 then raise exception 'uncertainty required'using errcode='22023';end if;
if (v->>'gas')='R-410A'and (v->>'equipment')='fixed_hvac'then gwp:=1924;locator:='Emission Factors Hub!D575';elsif (v->>'gas')='HFC-134a'and (v->>'equipment')='fixed_refrigeration'then gwp:=1300;locator:='Emission Factors Hub!E532';elsif (v->>'gas')='HFC-227ea'and (v->>'equipment')in('fixed_fire_suppression','portable_fire_suppression')then gwp:=3350;locator:='Emission Factors Hub!E538';else raise exception 'unsupported gas/equipment'using errcode='22023';end if;
perform neuvetra.m71_keys((v->'declarations'),'full_year_operational_control,california_office_or_distribution,no_installation_retirement_or_retrofit,no_stocks_recovery_reuse_or_transfer,complete_all_provider_service_records,all_known_releases_recorded,opening_full_charge_verified,closing_full_charge_verified');if exists(select 1 from jsonb_each((v->'declarations'))x where x.value is distinct from 'true'::jsonb)then raise exception 'explicit eligible facts required'using errcode='22023';end if;perform neuvetra.m71_keys((v->'evidence'),'asset_identity,capacity,opening_full_charge,closing_full_charge,annual_contractor_record');for r in select value from jsonb_each((v->'evidence'))loop perform neuvetra.m77_id(r);end loop;
if jsonb_typeof((v->'refills'))is distinct from 'array'or jsonb_typeof((v->'releases'))is distinct from 'array'or jsonb_array_length((v->'refills'))>100 or jsonb_array_length((v->'releases'))>100 then raise exception 'event capacity'using errcode='22023';end if;if jsonb_array_length((v->'refills'))=0 then perform neuvetra.m77_id((v->'zero_activity_evidence'));if jsonb_array_length((v->'releases'))>0 then raise exception 'unrecharged release'using errcode='22023';end if;elsif (v->'zero_activity_evidence')is distinct from 'null'::jsonb then raise exception 'zero conflicts with refill'using errcode='22023';end if;
for r in select value from jsonb_array_elements((v->'refills'))loop perform neuvetra.m71_keys(r,'id,date,kg,contractor,reference');perform neuvetra.m77_id((r->'id'));perform neuvetra.m77_id((r->'contractor'));perform neuvetra.m77_id((r->'reference'));perform neuvetra.m77_date((r->'date'));if (r->>'id')=any(ids)or((r->>'contractor')||'|'||(r->>'reference'))=any(refs)then raise exception 'duplicate refill'using errcode='22023';end if;ids:=array_append(ids,(r->>'id'));refs:=array_append(refs,(r->>'contractor')||'|'||(r->>'reference'));total:=total+neuvetra.m77_kg((r->'kg'),true);end loop;
for r in select value from jsonb_array_elements((v->'releases'))loop perform neuvetra.m71_keys(r,'id,date,kg,evidence,refill_id,preceded_refill_verified');perform neuvetra.m77_id((r->'id'));perform neuvetra.m77_id((r->'evidence'));perform neuvetra.m77_id((r->'refill_id'));if (r->'preceded_refill_verified')is distinct from 'true'::jsonb or (r->>'id')=any(ids)or (r->>'evidence')=any(release_refs)then raise exception 'duplicate/unverified release'using errcode='22023';end if;ids:=array_append(ids,(r->>'id'));release_refs:=array_append(release_refs,(r->>'evidence'));select x into linked from jsonb_array_elements((v->'refills'))x where (x->>'id')=(r->>'refill_id');if linked is null or neuvetra.m77_date((r->'date'))>neuvetra.m77_date((linked->'date'))then raise exception 'missing/reversed refill link'using errcode='22023';end if;perform neuvetra.m77_kg((r->'kg'),true);select sum(neuvetra.m77_kg((x->'kg'),true))into release_mass from jsonb_array_elements((v->'releases'))x where (x->>'refill_id')=(r->>'refill_id');if release_mass>neuvetra.m77_kg((linked->'kg'),true)then raise exception 'releases exceed refill'using errcode='22023';end if;end loop;
return jsonb_build_object('status','candidate_method_estimate','method','m77-stable-serviced-equipment-2025-candidate-v1','gas',(v->'gas'),'gwp',gwp::text,'gwp_basis','EPA January 2025 Hub; AR5 100-year published value','factor_locator',locator,'factor_source_sha256','43afb91d79b2ae765b3a447549d9e1021a144a407cec5eb804be9fcf69a668a7','guidance_sha256','fb3dd5c9677096094c2acef769c7fe2fb90def6feac403cf9c817f5810928d88','estimated_emitted_kg',neuvetra.m76_diesel_exact(total),'kg_co2e_exact',neuvetra.m76_diesel_exact(total*gwp),'kg_co2e_display',neuvetra.m76_diesel_display(total*gwp),'refill_count',jsonb_array_length((v->'refills')),'known_release_count',jsonb_array_length((v->'releases')),'evidence_verified',false,'limitation','Declared evidence is not verified by this calculator. Candidate service-based estimate; no measured-zero or complete-inventory claim.');end $$;

create function neuvetra.m77_source_findings(a jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when (a->'calculatorInput')='null'::jsonb then jsonb_build_array(jsonb_build_object('code','method_input_missing','message','Required method facts and service evidence are incomplete or unsupported; no candidate estimate.','blocking',true,'assetId',(a->'assetId'),'sourceId',(a#>'{binding,sourceId}')))else '[]'::jsonb end$$;
create function neuvetra.m77_evidence_text(target_company uuid,asset text,s jsonb)returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select 'SYNTHETIC — NOT AN ORIGINAL SERVICE RECORD OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(jsonb_build_object('companyId',target_company,'assetId',asset,'year',2025)||s)||chr(10)$$;

create function neuvetra.m77_validate_activity(family text,a jsonb,coverage jsonb)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare s jsonb:=(coverage->'snapshot');b jsonb;src jsonb;e jsonb;f jsonb;bd jsonb;r jsonb;k text;d jsonb;list jsonb;node text;rel jsonb;seen text[]:='{}';begin
if family='source'then perform neuvetra.m71_keys(a,'profile,binding,label,assetId,equipment,gas,capacityKg,calculatorInput,evidenceStatements');if (a->>'profile')is distinct from 'synthetic-fugitive-source-v1'then raise exception 'source profile'using errcode='22023';end if;b:=(a->'binding');perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');if (b->>'coverageVersionId')is distinct from (coverage->>'id')or (b->>'coverageVersionSha256')is distinct from (coverage->>'versionSha256')then raise exception 'coverage binding'using errcode='22023';end if;
select x into e from jsonb_array_elements((s->'entities'))x where (x->>'id')=(b->>'entityId');select x into f from jsonb_array_elements((s->'facilities'))x where (x->>'id')=(b->>'facilityId');select x into src from jsonb_array_elements((s->'sources'))x where (x->>'id')=(b->>'sourceId');select x into bd from jsonb_array_elements((s->'boundaryDecisions'))x where (x->>'id')=(b->>'boundaryDecisionId');if e is null or f is null or src is null or bd is null or (src->>'domain')is distinct from 'fugitive'or (src->>'entityId')is distinct from (e->>'id')or (src->>'facilityId')is distinct from (f->>'id')or (f->>'entityId')is distinct from (e->>'id')or (bd->>'entityId')is distinct from (e->>'id')then raise exception 'source binding facts'using errcode='22023';end if;
perform neuvetra.m76_diesel_text((a->'label'),120);perform neuvetra.m77_id((a->'assetId'));if (a->>'equipment')is null or (a->>'equipment')not in('fixed_hvac','fixed_refrigeration','fixed_fire_suppression','portable_fire_suppression','mobile_hvac','mobile_refrigeration','other','unknown')then raise exception 'equipment type'using errcode='22023';end if;if (a->'gas')<>'null'::jsonb then perform neuvetra.m76_diesel_text((a->'gas'),80);end if;if (a->'capacityKg')<>'null'::jsonb then perform neuvetra.m77_kg((a->'capacityKg'));end if;if jsonb_typeof((a->'evidenceStatements'))is distinct from 'array'or jsonb_array_length((a->'evidenceStatements'))>210 then raise exception 'evidence capacity'using errcode='22023';end if;for r in select value from jsonb_array_elements((a->'evidenceStatements'))loop perform neuvetra.m71_keys(r,'reference,issuer,description');perform neuvetra.m77_id((r->'reference'));perform neuvetra.m76_diesel_text((r->'issuer'),120);perform neuvetra.m76_diesel_text((r->'description'),2000);if length((r->>'description'))<20 then raise exception 'evidence statement missing facts'using errcode='22023';end if;end loop;if(select count(distinct (x->>'reference'))from jsonb_array_elements((a->'evidenceStatements'))x)<>jsonb_array_length((a->'evidenceStatements'))then raise exception 'duplicate evidence'using errcode='22023';end if;
if (a->'calculatorInput')<>'null'::jsonb then r:=(a->'calculatorInput');perform neuvetra.m77_calculate(r);if (r->>'asset_id')is distinct from (a->>'assetId')or (r->'equipment')is distinct from (a->'equipment')or (r->'gas')is distinct from (a->'gas')or (r->'opening_capacity')is distinct from (a->'capacityKg')then raise exception 'source input facts conflict'using errcode='22023';end if;if (s->>'consolidationApproach')is distinct from 'operational_control'or (e->>'countryCode')<>'US'or (e->>'regionCode')is distinct from 'CA'or (f->>'countryCode')<>'US'or (f->>'regionCode')is distinct from 'CA'or (bd->>'disposition')<>'included_activity'or (bd->'reason')='null'::jsonb or jsonb_array_length((bd->'evidenceRefs'))=0 then raise exception 'unsupported method corporate facts'using errcode='22023';end if;if jsonb_array_length(src->'evidenceRefs')=0 or s#>>'{period,start}'<>'2025-01-01'or s#>>'{period,endExclusive}'<>'2026-01-01'or not exists(select 1 from jsonb_array_elements(s->'coverageItems')i where i->>'domain'='fugitive'and i->>'sourceId'=src->>'id'and i->>'entityId'=e->>'id'and i->>'disposition'='included_activity'and i->>'start'='2025-01-01'and i->>'endExclusive'='2026-01-01'and i->>'evidenceState'='linked'and i->>'activityDataState'in('entered','explicit_zero')and i->'reason'<>'null'::jsonb and jsonb_array_length(i->'evidenceRefs')>0)then raise exception 'source screening missing'using errcode='22023';end if;for list in select value from jsonb_array_elements(r->'refills')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')st where st->'reference'=list->'reference'and st->'issuer'=list->'contractor')then raise exception 'servicing evidence contractor mismatch'using errcode='22023';end if;end loop;for list in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if (list->>'start')<>'2025-01-01'or (list->>'endExclusive')<>'2026-01-01'then raise exception 'method corporate period'using errcode='22023';end if;end loop;node:=(e->>'id');loop if node=any(seen)then raise exception 'relationship cycle'using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements((s->'relationships'))x where (x->>'childEntityId')=node;exit when rel is null;if (rel->>'start')<>'2025-01-01'or (rel->>'endExclusive')<>'2026-01-01'or (rel->>'ownershipPercent')is distinct from '100'or (rel->'controlFacts')='null'::jsonb or jsonb_array_length((rel->'evidenceRefs'))=0 then raise exception 'incomplete corporate control'using errcode='22023';end if;node:=(rel->>'parentEntityId');end loop;
for k in select (value#>>'{}')from jsonb_each((r->'evidence'))union all select (x->>'reference')from jsonb_array_elements((r->'refills'))x union all select (x->>'evidence')from jsonb_array_elements((r->'releases'))x union all select (r->>'zero_activity_evidence')where (r->'zero_activity_evidence')<>'null'::jsonb loop if not exists(select 1 from jsonb_array_elements((a->'evidenceStatements'))x where (x->>'reference')=k)then raise exception 'unresolved evidence reference'using errcode='22023';end if;end loop;end if;
else perform neuvetra.m71_keys(a,'profile,coverageVersionId,coverageVersionSha256,declaration');if (a->>'profile')is distinct from 'synthetic-fugitive-population-v1'or (a->>'coverageVersionId')is distinct from (coverage->>'id')or (a->>'coverageVersionSha256')is distinct from (coverage->>'versionSha256')then raise exception 'population binding'using errcode='22023';end if;d:=(a->'declaration');if d<>'null'::jsonb then perform neuvetra.m71_keys(d,'issuer,reference,description,discoveryBasis,completeness,coveredEntityIds,coveredFacilityIds,controlledFleetChecked,allControlledLocationsIncluded,assets');perform neuvetra.m76_diesel_text((d->'issuer'),120);perform neuvetra.m77_id((d->'reference'));perform neuvetra.m76_diesel_text((d->'description'),2000);perform neuvetra.m76_diesel_text((d->'discoveryBasis'),2000);if length((d->>'discoveryBasis'))<20 or (d->>'completeness')is null or (d->>'completeness')not in('unknown','partial','declared_complete')or jsonb_typeof((d->'controlledFleetChecked'))is distinct from 'boolean'or jsonb_typeof((d->'allControlledLocationsIncluded'))is distinct from 'boolean'then raise exception 'population discovery facts'using errcode='22023';end if;foreach k in array array['coveredEntityIds','coveredFacilityIds']loop if jsonb_typeof(d->k)is distinct from 'array'or jsonb_array_length(d->k)>25 or(select count(distinct x)from jsonb_array_elements_text(d->k)x)<>jsonb_array_length(d->k)then raise exception 'location declaration capacity/duplicates'using errcode='22023';end if;for node in select value from jsonb_array_elements_text(d->k)loop if node!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then raise exception 'location UUID'using errcode='22023';end if;end loop;end loop;if jsonb_typeof((d->'assets'))is distinct from 'array'or jsonb_array_length((d->'assets'))>25 then raise exception 'physical population capacity'using errcode='54000';end if;for r in select value from jsonb_array_elements((d->'assets'))loop perform neuvetra.m71_keys(r,'assetId,entityId,facilityId,equipment,gas,capacityKg,controlBasis,explanation,sourceId');perform neuvetra.m77_id((r->'assetId'));if (r->>'equipment')is null or (r->>'equipment')not in('fixed_hvac','fixed_refrigeration','fixed_fire_suppression','portable_fire_suppression','mobile_hvac','mobile_refrigeration','other','unknown')or (r->>'controlBasis')is null or (r->>'controlBasis')not in('owned_operational_control_full_year','unknown','partial_year','other')then raise exception 'asset classification/control facts'using errcode='22023';end if;foreach k in array array['entityId','facilityId','sourceId']loop if r->k<>'null'::jsonb and(jsonb_typeof(r->k)is distinct from 'string'or r->>k!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')or(k='entityId'and r->k='null'::jsonb)then raise exception 'asset corporate UUID'using errcode='22023';end if;end loop;if (r->'gas')<>'null'::jsonb then perform neuvetra.m76_diesel_text((r->'gas'),80);end if;if (r->'capacityKg')<>'null'::jsonb then perform neuvetra.m77_kg((r->'capacityKg'));end if;perform neuvetra.m76_diesel_text((r->'explanation'),2000);if length((r->>'explanation'))<20 then raise exception 'asset facts explanation required'using errcode='22023';end if;end loop;end if;end if;end $$;

create function neuvetra.m77_f(code text,message text,asset text default null,source text default null)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_array(jsonb_build_object('code',code,'message',message,'blocking',true,'assetId',asset,'sourceId',source))$$;
create function neuvetra.m77_reconciliation(target_company uuid,coverage jsonb,workpapers jsonb,population jsonb,review jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare deps jsonb:=neuvetra.m77_dependencies(coverage,workpapers);d jsonb:=(population#>'{activity,declaration}');findings jsonb:='[]';assets jsonb:=coalesce(nullif((d->'assets'),'null'::jsonb),'[]');sources jsonb:=coalesce((select jsonb_agg(x order by n)from jsonb_array_elements((coverage#>'{snapshot,sources}'))with ordinality q(x,n)where (x->>'domain')='fugitive'),'[]');a jsonb;s jsonb;w jsonb;x jsonb;ws jsonb;body jsonb;begin
if coverage is null then findings:=findings||neuvetra.m77_f('coverage_missing','Corporate coverage is missing.');end if;if (coverage#>>'{review,decision}')is distinct from 'accepted_bounded_internal'then findings:=findings||neuvetra.m77_f('coverage_review_required','Corporate coverage requires separate internal review.');end if;if population is null then findings:=findings||neuvetra.m77_f('population_missing','Independent physical fugitive population has not been declared.');end if;if population is not null and((population#>>'{activity,coverageVersionId}')is distinct from (coverage->>'id')or (population#>>'{activity,coverageVersionSha256}')is distinct from (coverage->>'versionSha256'))then findings:=findings||neuvetra.m77_f('stale_coverage','Population is bound to an earlier corporate boundary.');end if;if population is not null and (population#>>'{dependencies,dependencySha256}')is distinct from (deps->>'dependencySha256')then findings:=findings||neuvetra.m77_f('stale_dependencies','Rebind the population to current source workpapers and reviews.');end if;if d is null or d='null'::jsonb then findings:=findings||neuvetra.m77_f('declaration_missing','Independent discovery statement is missing.');else
if (d->>'completeness')<>'declared_complete'or (d->'allControlledLocationsIncluded')<>'true'::jsonb or (d->'controlledFleetChecked')<>'true'::jsonb or jsonb_array_length(assets)=0 then findings:=findings||neuvetra.m77_f('discovery_incomplete','Discovery must explicitly cover the full controlled physical population and fleet.');end if;for x in select value from jsonb_array_elements((coverage#>'{snapshot,entities}'))loop if not (d->'coveredEntityIds')? ((x->>'id'))then findings:=findings||neuvetra.m77_f('entity_omitted','A corporate entity is absent from discovery.');end if;end loop;for x in select value from jsonb_array_elements((coverage#>'{snapshot,facilities}'))loop if not (d->'coveredFacilityIds')? ((x->>'id'))then findings:=findings||neuvetra.m77_f('facility_omitted','A corporate facility is absent from discovery.');end if;end loop;for x in select value from jsonb_array_elements((d->'coveredEntityIds'))loop if not exists(select 1 from jsonb_array_elements((coverage#>'{snapshot,entities}'))e where (e->'id')=x)then findings:=findings||neuvetra.m77_f('unknown_entity','Discovery includes an unknown corporate entity.');end if;end loop;for x in select value from jsonb_array_elements((d->'coveredFacilityIds'))loop if not exists(select 1 from jsonb_array_elements((coverage#>'{snapshot,facilities}'))f where (f->'id')=x)then findings:=findings||neuvetra.m77_f('unknown_facility','Discovery includes an unknown corporate facility.');end if;end loop;end if;
for a in select value from jsonb_array_elements(assets)loop
if(select count(*)from jsonb_array_elements(assets)x where (x->'assetId')=(a->'assetId'))>1 then findings:=findings||neuvetra.m77_f('duplicate_asset','Physical device identity is duplicated.',(a->>'assetId'),(a->>'sourceId'));end if;if not exists(select 1 from jsonb_array_elements((coverage#>'{snapshot,entities}'))e where (e->'id')=(a->'entityId'))or((a->'facilityId')<>'null'::jsonb and not exists(select 1 from jsonb_array_elements((coverage#>'{snapshot,facilities}'))f where (f->'id')=(a->'facilityId')and (f->'entityId')=(a->'entityId')))then findings:=findings||neuvetra.m77_f('unknown_asset_location','Physical asset location is unresolved.',(a->>'assetId'),(a->>'sourceId'));end if;select x into s from jsonb_array_elements(sources)x where (x->'id')=(a->'sourceId');if s is null then findings:=findings||neuvetra.m77_f('unmatched_asset','Physical asset has no corporate fugitive source.',(a->>'assetId'),(a->>'sourceId'));elsif (s->'entityId')is distinct from (a->'entityId')or (s->'facilityId')is distinct from (a->'facilityId')then findings:=findings||neuvetra.m77_f('asset_source_mismatch','Physical and corporate source locations conflict.',(a->>'assetId'),(a->>'sourceId'));end if;if (a->'sourceId')<>'null'::jsonb and(select count(*)from jsonb_array_elements(assets)x where (x->'sourceId')=(a->'sourceId'))>1 then findings:=findings||neuvetra.m77_f('duplicate_source_mapping','Multiple devices share one corporate source.',(a->>'assetId'),(a->>'sourceId'));end if;
if (a->'gas')='null'::jsonb or (a->'capacityKg')='null'::jsonb or coalesce(((a->>'capacityKg'))::numeric,0)<=0 or (a->>'controlBasis')<>'owned_operational_control_full_year'or not(((a->>'gas')='R-410A'and (a->>'equipment')='fixed_hvac')or((a->>'gas')='HFC-134a'and (a->>'equipment')='fixed_refrigeration')or((a->>'gas')='HFC-227ea'and (a->>'equipment')in('fixed_fire_suppression','portable_fire_suppression')))then findings:=findings||neuvetra.m77_f('unsupported_asset','Gas, equipment, charge or operational control is unsupported.',(a->>'assetId'),(a->>'sourceId'));end if;
select coalesce(jsonb_agg(x order by n),'[]')into ws from jsonb_array_elements(workpapers)with ordinality q(x,n)where (x#>'{activity,assetId}')=(a->'assetId')and (x#>'{activity,binding,sourceId}')=(a->'sourceId');if jsonb_array_length(ws)<>1 then findings:=findings||neuvetra.m77_f('workpaper_missing_or_duplicate','Physical device requires exactly one effective workpaper.',(a->>'assetId'),(a->>'sourceId'));end if;for w in select value from jsonb_array_elements(ws)loop
if (w#>'{activity,binding,entityId}')is distinct from (a->'entityId')or (w#>'{activity,binding,facilityId}')is distinct from (a->'facilityId')or (w#>'{activity,gas}')is distinct from (a->'gas')or (w#>'{activity,equipment}')is distinct from (a->'equipment')or (w#>'{activity,capacityKg}')is distinct from (a->'capacityKg')then findings:=findings||neuvetra.m77_f('workpaper_asset_mismatch','Workpaper and physical device facts conflict.',(a->>'assetId'),(a->>'sourceId'));end if;if (w#>>'{activity,binding,coverageVersionId}')is distinct from (coverage->>'id')or (w#>>'{activity,binding,coverageVersionSha256}')is distinct from (coverage->>'versionSha256')then findings:=findings||neuvetra.m77_f('stale_workpaper','Source workpaper is bound to an earlier corporate boundary.',(a->>'assetId'),(a->>'sourceId'));end if;if (w->'calculation')='null'::jsonb or jsonb_array_length((w->'findings'))>0 then findings:=findings||neuvetra.m77_f('workpaper_blocked','Source method facts or evidence remain unresolved.',(a->>'assetId'),(a->>'sourceId'));end if;if (w#>>'{review,decision}')is distinct from 'accepted_bounded_internal'then findings:=findings||neuvetra.m77_f('source_review_required','Exact source workpaper requires separate internal review.',(a->>'assetId'),(a->>'sourceId'));end if;end loop;end loop;
for s in select value from jsonb_array_elements(sources)loop if not exists(select 1 from jsonb_array_elements(assets)a where (a->'sourceId')=(s->'id'))then findings:=findings||neuvetra.m77_f('orphan_source','Corporate fugitive source is absent from physical discovery.',null,(s->>'id'));end if;end loop;for w in select value from jsonb_array_elements(workpapers)loop if not exists(select 1 from jsonb_array_elements(assets)a where (a->'assetId')=(w#>'{activity,assetId}')and (a->'sourceId')=(w#>'{activity,binding,sourceId}'))then findings:=findings||neuvetra.m77_f('orphan_workpaper','Workpaper is absent from the physical/corporate source union.',(w#>>'{activity,assetId}'),(w#>>'{activity,binding,sourceId}'));end if;end loop;
if (review#>>'{decision}')is distinct from 'accepted_bounded_reconciliation'then findings:=findings||neuvetra.m77_f('population_review_required','Exact population reconciliation requires separate internal review.');end if;body:=jsonb_build_object('companyId',target_company,'dependencies',deps,'dependencySha256',(deps->'dependencySha256'),'populationVersionPin',case when population is null then 'null'::jsonb else jsonb_build_object('id',(population->'id'),'sha256',(population->'versionSha256'))end,'reviewPin',case when review is null then 'null'::jsonb else jsonb_build_object('id',(review->'id'),'sha256',(review->'decisionSha256'))end,'status',case when jsonb_array_length(findings)=0 then 'reconciled_bounded_synthetic'else 'blocked'end,'findings',findings,'assets',assets,'sourceIds',coalesce((select jsonb_agg((x->'id')order by n)from jsonb_array_elements(sources)with ordinality q(x,n)),'[]'),'worksheetIds',coalesce((select jsonb_agg((x->'streamId')order by (x->>'streamId')collate "C")from jsonb_array_elements(workpapers)x),'[]'),'emissionsTotals',null,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','limitations','["synthetic_only","declared_fugitive_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb);return body||jsonb_build_object('contentSha256',neuvetra.m67_hash(body));end $$;
create function neuvetra.m77_validate_population_correction(previous jsonb,current jsonb)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$begin if exists(select 1 from jsonb_array_elements(coalesce(previous#>'{declaration,assets}','[]'::jsonb))old_asset where not exists(select 1 from jsonb_array_elements(coalesce(current#>'{declaration,assets}','[]'::jsonb))new_asset where new_asset->'assetId'=old_asset->'assetId'))then raise exception 'previously discovered physical devices cannot be removed in the bounded 2025 profile'using errcode='22023';end if;end $$;
create function neuvetra.m77_history_capacity(target_company uuid,extra integer)returns void language plpgsql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if(select coalesce(sum(octet_length(convert_to(export_text,'utf8'))),0)from neuvetra.fugitive_versions where company_id=target_company)+(select coalesce(sum(octet_length(convert_to((payload->>'html'),'utf8'))+octet_length(convert_to((payload->>'snapshotJson'),'utf8'))),0)from neuvetra.fugitive_reports where company_id=target_company)+extra>8000000 then raise exception 'fugitive retained history capacity'using errcode='54000';end if;end $$;
create function neuvetra.save_fugitive_version(target_company uuid,target_stream uuid,family text,request jsonb,p jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare actor uuid:=auth.uid();a jsonb;old record;head record;prior jsonb;cv jsonb;deps jsonb;body jsonb;contributors jsonb;statement jsonb;expected_statement jsonb;statement_input jsonb;statement_text text;fingerprint text;new_stream uuid:=((p->>'streamId'))::uuid;new_id uuid:=((p->>'id'))::uuid;captured timestamptz:=((p->>'createdAt'))::timestamptz;r jsonb;reservation_kind text;reservation_key text;existing_asset text;begin
if not neuvetra.m77_lock(target_company,true)then raise exception 'forbidden'using errcode='42501';end if;if family not in('source','population')or family is null then raise exception 'family'using errcode='22023';end if;
perform neuvetra.m71_keys(request,case when family='source'then 'profile,binding,label,assetId,equipment,gas,capacityKg,calculatorInput,evidenceStatements,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey'else 'profile,coverageVersionId,coverageVersionSha256,declaration,expectedDependencySha256,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey'end);perform neuvetra.m71_keys(p,'id,companyId,streamId,family,version,previousVersionId,previousVersionSha256,createdBy,createdAt,contributorIds,correctionReason,coverageVersion,statements,dependencies,findings,activity,calculation,inputSha256,contentSha256,versionSha256,synthetic,scope1Completeness,corporateCompleteness,releaseEligible,assurance,emissionsTotals,review');fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'family',family,'streamId',target_stream,'request',request-'idempotencyKey'));select * into old from neuvetra.fugitive_requests where company_id=target_company and idempotency_key=((request->>'idempotencyKey'))::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save'or old.actor_id<>actor then raise exception 'idempotency conflict'using errcode='23505';end if;return old.record_id;end if;
cv:=neuvetra.m77_current_coverage(target_company);if cv is null then raise exception 'coverage missing'using errcode='22023';end if;cv:=cv||jsonb_build_object('review',null);a:=request-array['expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey','expectedDependencySha256'];perform neuvetra.m77_validate_activity(family,a,cv);deps:=case when family='population'then neuvetra.m77_current_dependencies(target_company)else 'null'::jsonb end;if family='population'and (request->>'expectedDependencySha256')is distinct from (deps->>'dependencySha256')then raise exception 'dependencies changed'using errcode='23505';end if;
select * into head from neuvetra.fugitive_heads where company_id=target_company and id=target_stream and fugitive_heads.family=save_fugitive_version.family;if target_stream is null then if (request->'expectedVersionId')<>'null'::jsonb or (request->'expectedVersionSha256')<>'null'::jsonb or (request->'correctionReason')<>'null'::jsonb then raise exception 'first version pins'using errcode='22023';end if;else if head.id is null then raise exception 'stream changed'using errcode='23505';end if;select payload into prior from neuvetra.fugitive_versions where company_id=target_company and id=head.version_id;if (request->>'expectedVersionId')is distinct from (prior->>'id')or (request->>'expectedVersionSha256')is distinct from (prior->>'versionSha256')then raise exception 'predecessor changed'using errcode='23505';end if;perform neuvetra.m76_diesel_text((request->'correctionReason'),500);if (prior->'activity')=a and (prior->'dependencies')=deps then raise exception 'no-op correction'using errcode='23505';end if;if family='source'and (prior#>>'{activity,assetId}')<>(a->>'assetId')then raise exception 'physical identity immutable'using errcode='22023';end if;end if;
if family='population'then perform neuvetra.m77_validate_population_correction(prior->'activity',a);end if;
if(select count(*)from neuvetra.fugitive_versions where company_id=target_company)>=40 or(target_stream is null and family='source'and(select count(*)from neuvetra.fugitive_heads where company_id=target_company and fugitive_heads.family='source')>=8)then raise exception 'fugitive version/source capacity'using errcode='54000';end if;
select coalesce(jsonb_agg(x order by x collate "C"),'[]')into contributors from(select distinct x from(select jsonb_array_elements_text(coalesce((prior->'contributorIds'),'[]'))x union all select jsonb_array_elements_text((cv->'contributorIds'))union all select actor::text union all select jsonb_array_elements_text((w->'contributorIds'))from jsonb_array_elements(case when family='population'then neuvetra.m77_current_workpapers(target_company)else '[]'::jsonb end)w)q)t;
if (p->>'companyId')is distinct from target_company::text or (p->>'family')is distinct from family or (p->>'createdBy')is distinct from actor::text or (p->'previousVersionId')is distinct from coalesce((prior->'id'),'null'::jsonb)or (p->'previousVersionSha256')is distinct from coalesce((prior->'versionSha256'),'null'::jsonb)or (p->'version')is distinct from to_jsonb(coalesce(((prior->>'version'))::integer,0)+1)or(target_stream is not null and new_stream<>target_stream)or (p->'contributorIds')is distinct from contributors or (p->'correctionReason')is distinct from (request->'correctionReason')or (p->'activity')is distinct from a or (p->'coverageVersion')is distinct from cv or (p->'dependencies')is distinct from deps or (p->'review')is distinct from 'null'::jsonb or (p->'synthetic')is distinct from 'true'::jsonb or (p->>'scope1Completeness')is distinct from 'incomplete'or (p->>'corporateCompleteness')is distinct from 'incomplete'or (p->'releaseEligible')is distinct from 'false'::jsonb or (p->>'assurance')is distinct from 'none'or (p->'emissionsTotals')is distinct from 'null'::jsonb or abs(extract(epoch from(clock_timestamp()-captured)))>300 or captured<coalesce(((prior->>'createdAt'))::timestamptz,captured)then raise exception 'invalid retained version'using errcode='22023';end if;
if (p->'findings')is distinct from(case when family='source'then neuvetra.m77_source_findings(a)else '[]'::jsonb end)or (p->'calculation')is distinct from(case when family='source'and (a->'calculatorInput')<>'null'::jsonb then neuvetra.m77_calculate((a->'calculatorInput'))else 'null'::jsonb end)then raise exception 'invalid calculation/findings'using errcode='22023';end if;
if jsonb_typeof((p->'statements'))is distinct from 'array'or jsonb_array_length((p->'statements'))is distinct from(case when family='source'then jsonb_array_length((a->'evidenceStatements'))when (a->'declaration')='null'::jsonb then 0 else 1 end)then raise exception 'statement count'using errcode='22023';end if;for statement in select value from jsonb_array_elements((p->'statements'))loop perform neuvetra.m71_keys(statement,'id,reference,issuer,description,locator,text,sha256,byteLength');if family='source'then select x into statement_input from jsonb_array_elements((a->'evidenceStatements'))x where (x->'reference')=(statement->'reference');else statement_input:=jsonb_build_object('reference',(a#>'{declaration,reference}'),'issuer',(a#>'{declaration,issuer}'),'description',(a#>>'{declaration,description}')||' Discovery basis: '||(a#>>'{declaration,discoveryBasis}'));end if;statement_text:=neuvetra.m77_evidence_text(target_company,case when family='source'then (a->>'assetId')else null end,statement_input);expected_statement:=statement_input||jsonb_build_object('id',(statement->'id'),'locator','m77-evidence:'||(statement->>'id')||':'||(statement->>'reference'),'text',statement_text,'sha256',encode(sha256(convert_to(statement_text,'utf8')),'hex'),'byteLength',octet_length(convert_to(statement_text,'utf8')));if statement_input is null or statement is distinct from expected_statement then raise exception 'statement semantic integrity'using errcode='22023';end if;end loop;if(select count(distinct (x->>'reference'))from jsonb_array_elements((p->'statements'))x)<>jsonb_array_length((p->'statements'))then raise exception 'duplicate retained statements'using errcode='22023';end if;
body:=jsonb_build_object('activity',a,'coverageVersion',cv,'statements',(p->'statements'),'dependencies',deps,'findings',(p->'findings'),'calculation',(p->'calculation'));if (p->>'inputSha256')is distinct from neuvetra.m67_hash(a)or (p->>'contentSha256')is distinct from neuvetra.m67_hash(body)or (p->>'versionSha256')is distinct from neuvetra.m67_hash(p-array['versionSha256','review'])then raise exception 'version digest integrity'using errcode='22023';end if;perform neuvetra.m77_history_capacity(target_company,octet_length(convert_to(neuvetra.m67_canonical(p),'utf8')));
if target_stream is null then insert into neuvetra.fugitive_heads values(new_stream,target_company,family,case when family='source'then((a#>>'{binding,sourceId}'))::uuid else null end,case when family='source'then (a->>'assetId')else null end,2025,null,0);end if;for statement in select value from jsonb_array_elements((p->'statements'))loop insert into neuvetra.fugitive_statements values(((statement->>'id'))::uuid,target_company,statement,(statement->>'sha256'),(statement->>'text'));end loop;
if family='source'and (a->'calculatorInput')<>'null'::jsonb then for r in select value from jsonb_array_elements((a#>'{calculatorInput,refills}'))union all select value from jsonb_array_elements((a#>'{calculatorInput,releases}'))loop foreach reservation_kind in array array['event',case when r?'contractor'then 'contractor_reference'else 'release_reference'end]loop reservation_key:=case when reservation_kind='event'then (r->>'id')when reservation_kind='contractor_reference'then lower((r->>'contractor'))||'|'||lower((r->>'reference'))else lower((r->>'evidence'))end;select asset_id into existing_asset from neuvetra.fugitive_event_reservations where company_id=target_company and year=2025 and fugitive_event_reservations.kind=reservation_kind and fugitive_event_reservations.event_key=reservation_key;if found and existing_asset<>(a->>'assetId')then raise exception 'event is reserved to another physical device'using errcode='23505';end if;insert into neuvetra.fugitive_event_reservations values(target_company,2025,reservation_kind,reservation_key,new_stream,(a->>'assetId'),captured)on conflict on constraint fugitive_event_reservations_pkey do nothing;end loop;end loop;end if;
insert into neuvetra.fugitive_versions values(new_id,target_company,new_stream,((p->>'version'))::integer,((p->>'previousVersionId'))::uuid,((cv->>'id'))::uuid,p,(p->>'inputSha256'),(p->>'contentSha256'),(p->>'versionSha256'),actor,captured,neuvetra.m67_canonical(p));update neuvetra.fugitive_heads set version_id=new_id,revision=((p->>'version'))::integer,source_id=case when family='source'then((a#>>'{binding,sourceId}'))::uuid else null end where company_id=target_company and id=new_stream;insert into neuvetra.fugitive_requests values(target_company,((request->>'idempotencyKey'))::uuid,actor,'save',family,target_stream,fingerprint,new_id);insert into neuvetra.fugitive_audit(id,company_id,record_id,kind,record_sha256,actor_id,created_at)values(gen_random_uuid(),target_company,new_id,'save',(p->>'versionSha256'),actor,captured);return new_id;end $$;

create function neuvetra.review_fugitive_version(target_company uuid,target_stream uuid,family text,request jsonb,p jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare actor uuid:=auth.uid();v jsonb;deps jsonb;old record;fingerprint text;begin if not neuvetra.m77_lock(target_company,true)then raise exception 'forbidden'using errcode='42501';end if;perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDependencySha256,decision,note,acknowledgedLimitations,idempotencyKey');perform neuvetra.m71_keys(p,'id,versionId,versionSha256,dependencies,decision,note,acknowledgedLimitations,reviewerId,reviewedAt,decisionSha256');fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'family',family,'streamId',target_stream,'request',request-'idempotencyKey'));select * into old from neuvetra.fugitive_requests where company_id=target_company and idempotency_key=((request->>'idempotencyKey'))::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'review'or old.actor_id<>actor then raise exception 'idempotency conflict'using errcode='23505';end if;return old.record_id;end if;select vv.payload into v from neuvetra.fugitive_heads h join neuvetra.fugitive_versions vv on vv.id=h.version_id and vv.company_id=h.company_id where h.company_id=target_company and h.id=target_stream and h.family=review_fugitive_version.family;if v is null or (v->>'id')is distinct from (request->>'versionId')or (v->>'versionSha256')is distinct from (request->>'expectedVersionSha256')then raise exception 'review version changed'using errcode='23505';end if;if (v->'contributorIds')?actor::text then raise exception 'contributors cannot review'using errcode='42501';end if;deps:=case when family='population'then neuvetra.m77_current_dependencies(target_company)else 'null'::jsonb end;if (request->'expectedDependencySha256')is distinct from(case when family='population'then (deps->'dependencySha256')else 'null'::jsonb end)or (v->'dependencies')is distinct from deps then raise exception 'review dependencies changed'using errcode='23505';end if;
perform neuvetra.m76_diesel_text((request->'note'),500);if (request->'acknowledgedLimitations')is distinct from '["synthetic_only","declared_fugitive_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb or (request->>'decision')is null or (request->>'decision')not in('changes_requested',case when family='source'then 'accepted_bounded_internal'else 'accepted_bounded_reconciliation'end)then raise exception 'review decision/limitations'using errcode='22023';end if;
if (request->>'decision')='accepted_bounded_internal'and((v->'calculation')='null'::jsonb or jsonb_array_length((v->'findings'))>0)then raise exception 'blocked source'using errcode='22023';end if;if (request->>'decision')='accepted_bounded_reconciliation'and neuvetra.m77_reconciliation(target_company,neuvetra.m77_current_coverage(target_company),neuvetra.m77_current_workpapers(target_company),v,p)->>'status'<>'reconciled_bounded_synthetic'then raise exception 'blocked reconciliation'using errcode='22023';end if;
if (p->>'reviewerId')is distinct from actor::text or (p->'versionId')is distinct from (v->'id')or (p->'versionSha256')is distinct from (v->'versionSha256')or (p->'dependencies')is distinct from deps or (p->'decision')is distinct from (request->'decision')or (p->'note')is distinct from (request->'note')or (p->'acknowledgedLimitations')is distinct from (request->'acknowledgedLimitations')or (p->>'decisionSha256')is distinct from neuvetra.m67_hash((p-'decisionSha256')||jsonb_build_object('companyId',target_company))or abs(extract(epoch from(clock_timestamp()-((p->>'reviewedAt'))::timestamptz)))>300 or((p->>'reviewedAt'))::timestamptz<((v->>'createdAt'))::timestamptz then raise exception 'review integrity'using errcode='22023';end if;insert into neuvetra.fugitive_reviews values(((p->>'id'))::uuid,target_company,((v->>'id'))::uuid,p,(p->>'decisionSha256'),actor,((p->>'reviewedAt'))::timestamptz);insert into neuvetra.fugitive_requests values(target_company,((request->>'idempotencyKey'))::uuid,actor,'review',family,target_stream,fingerprint,((p->>'id'))::uuid);insert into neuvetra.fugitive_audit(id,company_id,record_id,kind,record_sha256,actor_id,created_at)values(gen_random_uuid(),target_company,((p->>'id'))::uuid,'review',(p->>'decisionSha256'),actor,((p->>'reviewedAt'))::timestamptz);return((p->>'id'))::uuid;end $$;
create function neuvetra.m77_render_report(s jsonb)returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare v jsonb:=(s->'version');coverage jsonb:=coalesce(nullif(s#>'{proof,coverageVersion}','null'::jsonb),s#>'{version,coverageVersion}');labels jsonb:='{"fixed_hvac":"Fixed air conditioning","fixed_refrigeration":"Fixed refrigeration","fixed_fire_suppression":"Fixed fire suppression","portable_fire_suppression":"Portable fire suppression","mobile_hvac":"Vehicle air conditioning","mobile_refrigeration":"Refrigerated transport","owned_operational_control_full_year":"Owned and controlled throughout the year","partial_year":"Partial year — unsupported","other":"Other — unsupported","unknown":"Unknown","accepted_bounded_internal":"Accepted for this internal workpaper","accepted_bounded_reconciliation":"Accepted for this equipment reconciliation","changes_requested":"Changes requested","unreviewed":"Not reviewed"}'::jsonb;title text;status text;number text:='';statement_links text;asset_rows text;findings text;evidence_sections text;label text;company text;begin label:=case when (v->>'family')='source'then v#>>'{activity,label}'else 'Independent physical discovery'end;company:=coverage#>>'{snapshot,companyLabel}';title:=case when (v->>'family')='source'then 'Fugitive source workpaper'else 'Physical fugitive population reconciliation'end;status:=case when (v->>'family')='source'then case when (v->'calculation')<>'null'::jsonb then 'Candidate method estimate'else 'Blocked — incomplete or unsupported method facts'end else case when (s#>>'{reconciliation,status}')='reconciled_bounded_synthetic'then 'Declared synthetic population reconciled'else 'Blocked — open reconciliation findings'end end;
if (v->>'family')='source'and (v->'calculation')<>'null'::jsonb then number:='<p>Gas '||neuvetra.m76_html_escape((v#>>'{calculation,gas}'))||' · estimated emitted kg '||neuvetra.m76_html_escape((v#>>'{calculation,estimated_emitted_kg}'))||' · kg CO2e '||neuvetra.m76_html_escape((v#>>'{calculation,kg_co2e_display}'))||' (half-even, four decimals). Candidate AR5 GWP '||neuvetra.m76_html_escape((v#>>'{calculation,gwp}'))||'. Known releases are already reconciled inside refill activity and are not added again.</p>';end if;
select coalesce(string_agg('<li><a href="#evidence-'||neuvetra.m76_html_escape((x->>'id'))||'">'||neuvetra.m76_html_escape((x->>'reference'))||'</a> — '||neuvetra.m76_html_escape((x->>'issuer'))||' · '||neuvetra.m76_html_escape((x->>'locator'))||' · SHA-256 '||neuvetra.m76_html_escape((x->>'sha256'))||'</li>',''order by n),'')into statement_links from jsonb_array_elements((v->'statements'))with ordinality q(x,n);
select coalesce(string_agg('<section id="evidence-'||neuvetra.m76_html_escape(x->>'id')||'"><h3>'||neuvetra.m76_html_escape(x->>'reference')||' · '||neuvetra.m76_html_escape(x->>'issuer')||'</h3><p>'||neuvetra.m76_html_escape(x->>'description')||'</p><details><summary>Exact retained statement</summary><pre>'||neuvetra.m76_html_escape(x->>'text')||'</pre></details></section>',''order by n),'')into evidence_sections from jsonb_array_elements(v->'statements')with ordinality q(x,n);
select coalesce(string_agg('<tr><td data-label="Asset">'||neuvetra.m76_html_escape((x->>'assetId'))||'</td><td data-label="Equipment">'||neuvetra.m76_html_escape(coalesce(labels->>(x->>'equipment'),x->>'equipment'))||'</td><td data-label="Gas">'||neuvetra.m76_html_escape(coalesce((x->>'gas'),'Unknown'))||'</td><td data-label="Charge kg">'||neuvetra.m76_html_escape(coalesce((x->>'capacityKg'),'Unknown'))||'</td><td data-label="Corporate source">'||neuvetra.m76_html_escape(coalesce((select z->>'name'from jsonb_array_elements(coverage#>'{snapshot,sources}')z where z->>'id'=x->>'sourceId'),x->>'sourceId','Unknown'))||'</td><td data-label="Control">'||neuvetra.m76_html_escape(coalesce(labels->>(x->>'controlBasis'),x->>'controlBasis'))||'</td></tr>',''order by n),'')into asset_rows from jsonb_array_elements(coalesce((s#>'{reconciliation,assets}'),'[]'))with ordinality q(x,n);
select coalesce(string_agg('<li>'||neuvetra.m76_html_escape((x->>'message'))||'</li>',''order by n),'')into findings from jsonb_array_elements(coalesce((s#>'{reconciliation,findings}'),(v->'findings')))with ordinality q(x,n);
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>'||title||'</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:1000px;color:#172f2c;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%}th,td{padding:.4rem;text-align:left;border-bottom:1px solid #ccd8d0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}@media(max-width:600px){thead{display:none}tr{display:block;margin:.8rem 0}td{display:block}td::before{content:attr(data-label);font-weight:600;margin-right:.5rem}}@media print{body{font-size:10pt;margin:0}tr{break-inside:avoid}}</style></head><body><h1>'||title||' — synthetic internal draft</h1><p>Company '||neuvetra.m76_html_escape(company)||' · '||neuvetra.m76_html_escape(label)||'</p><p>'||neuvetra.m76_html_escape(status)||'</p><p>Calendar 2025 · version '||(v->>'version')||' · internal review: '||neuvetra.m76_html_escape(coalesce(labels->>coalesce(s#>>'{review,decision}','unreviewed'),coalesce(s#>>'{review,decision}','unreviewed')))||'.</p><p>No complete Scope 1 or corporate inventory claim. Candidate methods and factors are not released. Requirements are not determined. No external assurance. No emissions aggregation.</p>'||number||'<h2>Retained evidence</h2><ul>'||statement_links||'</ul>'||evidence_sections||'<h2>Physical devices</h2><table><thead><tr><th>Asset</th><th>Equipment</th><th>Gas</th><th>Charge kg</th><th>Corporate source</th><th>Control</th></tr></thead><tbody>'||asset_rows||'</tbody></table><h2>Open findings</h2><ul>'||findings||'</ul><details><summary>Exact retained data and provenance</summary><pre>'||neuvetra.m76_html_escape(neuvetra.m67_canonical(s))||'</pre></details></body></html>';end $$;
create function neuvetra.create_fugitive_report(target_company uuid,target_stream uuid,family text,request jsonb,p jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare actor uuid:=auth.uid();v jsonb;r jsonb;cv jsonb;works jsonb;deps jsonb;snapshot jsonb;expected jsonb;old record;fingerprint text;begin if not neuvetra.m77_lock(target_company,true)then raise exception 'forbidden'using errcode='42501';end if;perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDecisionId,expectedDecisionSha256,expectedReconciliationSha256,idempotencyKey');perform neuvetra.m71_keys(p,'id,companyId,streamId,family,versionId,versionSha256,createdBy,createdAt,rendererVersion,snapshotJson,snapshotSha256,html,htmlSha256,htmlByteLength,reportSha256');fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','report','actor',actor,'companyId',target_company,'family',family,'streamId',target_stream,'request',request-'idempotencyKey'));select * into old from neuvetra.fugitive_requests where company_id=target_company and idempotency_key=((request->>'idempotencyKey'))::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'report'or old.actor_id<>actor then raise exception 'idempotency conflict'using errcode='23505';end if;return old.record_id;end if;
select vv.payload into v from neuvetra.fugitive_versions vv join neuvetra.fugitive_heads h on h.id=vv.stream_id and h.company_id=vv.company_id where vv.company_id=target_company and h.id=target_stream and h.family=create_fugitive_report.family and vv.id=((request->>'versionId'))::uuid;if v is null or (v->>'versionSha256')is distinct from (request->>'expectedVersionSha256') then raise exception 'report version changed'using errcode='23505';end if;cv:=neuvetra.m77_current_coverage(target_company);works:=neuvetra.m77_current_workpapers(target_company);deps:=neuvetra.m77_dependencies(cv,works);select rr.payload into r from neuvetra.fugitive_reviews rr where rr.company_id=target_company and rr.version_id=((v->>'id'))::uuid and(case when family='source'then true else (rr.payload#>>'{dependencies,dependencySha256}')=(deps->>'dependencySha256')end);if (request->'expectedDecisionId')is distinct from coalesce((r->'id'),'null'::jsonb)or (request->'expectedDecisionSha256')is distinct from coalesce((r->'decisionSha256'),'null'::jsonb)then raise exception 'report review changed'using errcode='23505';end if;
if family='population'and not exists(select 1 from neuvetra.fugitive_heads h where h.company_id=target_company and h.id=target_stream and h.version_id=((v->>'id'))::uuid)then raise exception 'report population head changed'using errcode='23505';end if;
expected:=jsonb_build_object('profile','m77-report-snapshot-v1','version',v,'review',r,'reconciliation',case when family='population'then neuvetra.m77_reconciliation(target_company,cv,works,v,r)else null end,'proof',case when family='population'then jsonb_build_object('coverageVersion',cv,'workpaperVersions',works)else null end,'limitations','["synthetic_only","declared_fugitive_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb);snapshot:=((p->>'snapshotJson'))::jsonb;
if (request->'expectedReconciliationSha256')is distinct from coalesce((expected#>'{reconciliation,contentSha256}'),'null'::jsonb)then raise exception 'reconciliation changed'using errcode='23505';end if;if snapshot is distinct from expected or (p->>'snapshotJson')is distinct from neuvetra.m67_canonical(expected)or (p->>'html')is distinct from neuvetra.m77_render_report(expected)or (p->>'snapshotSha256')is distinct from encode(sha256(convert_to((p->>'snapshotJson'),'utf8')),'hex')or (p->>'htmlSha256')is distinct from encode(sha256(convert_to((p->>'html'),'utf8')),'hex')or (p->'htmlByteLength')is distinct from to_jsonb(octet_length(convert_to((p->>'html'),'utf8')))or (p->>'reportSha256')is distinct from neuvetra.m67_hash(p-array['html','snapshotJson','reportSha256'])or (p->>'companyId')is distinct from target_company::text or (p->>'streamId')is distinct from target_stream::text or (p->>'family')is distinct from family or (p->'versionId')is distinct from (v->'id')or (p->'versionSha256')is distinct from (v->'versionSha256')or (p->>'createdBy')is distinct from actor::text or (p->>'rendererVersion')is distinct from 'm77-retained-report-v1'or abs(extract(epoch from(clock_timestamp()-((p->>'createdAt'))::timestamptz)))>300 then raise exception 'report semantic integrity'using errcode='22023';end if;
if(select count(*)from neuvetra.fugitive_reports where company_id=target_company)>=80 then raise exception 'report capacity'using errcode='54000';end if;perform neuvetra.m77_history_capacity(target_company,octet_length(convert_to((p->>'html'),'utf8'))+octet_length(convert_to((p->>'snapshotJson'),'utf8')));insert into neuvetra.fugitive_reports values(((p->>'id'))::uuid,target_company,target_stream,((v->>'id'))::uuid,p,(p->>'reportSha256'),actor,((p->>'createdAt'))::timestamptz);insert into neuvetra.fugitive_requests values(target_company,((request->>'idempotencyKey'))::uuid,actor,'report',family,target_stream,fingerprint,((p->>'id'))::uuid);insert into neuvetra.fugitive_audit(id,company_id,record_id,kind,record_sha256,actor_id,created_at)values(gen_random_uuid(),target_company,((p->>'id'))::uuid,'report',(p->>'reportSha256'),actor,((p->>'createdAt'))::timestamptz);return((p->>'id'))::uuid;end $$;
do $$declare p record;begin for p in select oid::regprocedure signature,proname from pg_proc where pronamespace='neuvetra'::regnamespace and(proname like 'm77\_%'escape '\'or proname in('save_fugitive_version','review_fugitive_version','create_fugitive_report'))loop execute format('revoke all on function %s from public,authenticated,neuvetra_runtime',p.signature);if p.proname in('m77_lock','save_fugitive_version','review_fugitive_version','create_fugitive_report')then execute format('grant execute on function %s to neuvetra_runtime',p.signature);end if;end loop;end $$;




